function restartLoop(){if(!loopState||!player)return;try{player.seekTo(loopState.start,true);player.playVideo()}catch(e){}}
function startLoop(start,end,button){start=Math.max(0,+start||0);end=Math.max(start+2,+end||start+15);if(loopState&&loopState.start===start&&loopState.end===end){stopLoop(true);status("Kesit döngüsü durduruldu.","ok");return}if(!navigator.onLine){status("Çevrimdışıyken metin ve alıştırmalar kullanılabilir; video döngüsü internet ister.","error");return}var ready=(player&&playerVideoId===currentId)?Promise.resolve(player):setPlayerVideo(currentId);ready.then(function(){stopLoop(false);loopState={start:start,end:end,button:button,label:button.textContent};button.classList.add("is-looping");button.textContent="⏹ Döngüyü durdur";button.setAttribute("aria-pressed","true");restartLoop();loopTimer=setInterval(function(){if(!loopState||!player)return;try{var t=player.getCurrentTime();if(t>=loopState.end-.08||t<loopState.start-.8)restartLoop()}catch(e){}},180);status(time(start)+"–"+time(end)+" kesiti sen durdurana kadar dönüyor.","ok")}).catch(function(){status("YouTube oynatıcısı başlatılamadı.","error")})}
