async function finishFullStudy(id,url,meta,chunks,parts){var data=mergeChunks(meta,chunks,parts);await saveStudy(id,url,data);render(data);setBusy(false);status(time(meta.durationSeconds)+" videonun tamamındaki "+data.segments.length+" cümle IndexedDB'ye kaydedildi ve bulut senkronuna hazır.","ok");return data}
async function runApiChunks(url,id,meta,chunks){var parts=[];for(var i=0;i<chunks.length;i++){status("Gemini tüm videoyu çalışıyor: blok "+(i+1)+"/"+chunks.length+" · "+time(chunks[i].start)+"–"+time(chunks[i].end),"loading");var raw=await DHProviders.youtubeStudy(url,chunkPrompt(url,meta,chunks[i],chunks.length),{max_tokens:12000,temperature:.1});parts.push(normalizeChunk(raw,meta,chunks[i]))}return finishFullStudy(id,url,meta,chunks,parts)}
